<main id="primary" class="site-main blog-page section"><div class="container blog-container blog-container-<?php echo esc_attr( kimpu_blog_mod( 'container_width', 'default' ) ); ?>"><div class="blog-layout blog-sidebar-<?php echo esc_attr( kimpu_blog_sidebar_position() ); ?><?php echo kimpu_blog_sidebar_active() ? ' has-blog-sidebar' : ''; ?>" style="--blog-sidebar-width:<?php echo esc_attr( kimpu_blog_mod( 'sidebar_width', '280px' ) ); ?>"><div class="blog-main"><header class="blog-page-header section-heading"><h1><?php echo esc_html( get_the_title( get_option( 'page_for_posts' ) ) ?: __( 'Latest articles', 'kimpu-multipurpose' ) ); ?></h1><?php if ( get_option( 'page_for_posts' ) ) { $page = get_post( get_option( 'page_for_posts' ) ); if ( $page && $page->post_excerpt ) { echo '<p>' . esc_html( $page->post_excerpt ) . '</p>'; } } ?><?php get_search_form(); ?></header><?php kimpu_blog_category_links(); ?><?php if ( have_posts() ) : ?><div class="blog-results blog-layout-<?php echo esc_attr( kimpu_blog_layout() ); ?>"><?php $index = 0; while ( have_posts() ) : the_post(); if ( 0 === $index && kimpu_blog_mod( 'featured', true ) ) { get_template_part( 'template-parts/blog/featured-post' ); } else { kimpu_blog_render_post_item( 'magazine' === kimpu_blog_layout() ? 'magazine' : ( 'list' === kimpu_blog_layout() ? 'list' : 'card' ), 2 ); } $index++; endwhile; ?></div><?php kimpu_blog_pagination(); else : ?><?php get_template_part( 'template-parts/blog/empty-state' ); ?><?php endif; ?></div><?php if ( kimpu_blog_sidebar_active() ) : ?><aside class="blog-sidebar" aria-label="<?php esc_attr_e( 'Blog sidebar', 'kimpu-multipurpose' ); ?>"><?php dynamic_sidebar( 'blog-sidebar' ); ?></aside><?php endif; ?></div></div></main>
